import{_ as n,C as t,o,c,E as a,a2 as s}from"./chunks/framework.IIAdu7fg.js";const _=JSON.parse('{"title":"保留最佳尝试之后，科研智能体到底完成了什么？","description":"","frontmatter":{"title":"保留最佳尝试之后，科研智能体到底完成了什么？","date":"2026-10-22","column":"digital-employee","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"保留最高分尝试是否意味着过关及真正恢复？（Does retaining the highest-scoring attempt establish gate attainment and genuine recovery?）","summary":"一个最高分仍低于门槛的合成例子，说明产出保留、评分通过与科研过程恢复需要分别举证。","sources":"OmicsBench; ST-Bench; 2026-10-22 internal selector probe","pageClass":"runtime-v6-article","item_id":"SIG-20261022-003","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-22-sig-20261022-003-2026-10-22-scientific-best-attempt-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-10-22-scientific-best-attempt.md","filePath":"zh/digital-employee/2026-10-22-scientific-best-attempt.md","lastUpdated":1792681615000}'),l={name:"zh/digital-employee/2026-10-22-scientific-best-attempt.md"};function h(d,e,p,m,g,b){const r=t("ArticleCover"),i=t("ArticleTableScroll");return o(),c("div",null,[a(r,{image:"/assets/covers/daily-2026-10-22-sig-20261022-003-2026-10-22-scientific-best-attempt-cover.png",kicker:"研究成果",title:"保留最佳尝试之后，科研智能体到底完成了什么？",summary:"一个最高分仍低于门槛的合成例子，说明产出保留、评分通过与科研过程恢复需要分别举证。",version:"2026-10-22",languageHref:"/en/digital-employee/2026-10-22-scientific-best-attempt",languageLabel:"English"}),a(i,{language:"zh"}),e[0]||(e[0]=s('<h1 id="保留最佳尝试之后-科研智能体到底完成了什么" tabindex="-1">保留最佳尝试之后，科研智能体到底完成了什么？ <a class="header-anchor" href="#保留最佳尝试之后-科研智能体到底完成了什么" aria-label="Permalink to &quot;保留最佳尝试之后，科研智能体到底完成了什么？&quot;">​</a></h1><p>三次尝试分别得到 0.6、0.5、0.4，系统保留第一份结果。它选对了最高分，却没有达到 0.7 的门槛。这个合成例子提醒科研智能体的评测设计者：有结果可保留、结果过关、分析过程得到纠正，是三个不同判断。完成记录应分别展示它们，读者也应据此检查“恢复成功”的依据。</p><h2 id="最高分不负责判定过关" tabindex="-1">最高分不负责判定过关 <a class="header-anchor" href="#最高分不负责判定过关" aria-label="Permalink to &quot;最高分不负责判定过关&quot;">​</a></h2><p>OmicsBench（多组学科研任务评测基准）把连续交互组织成 97 个任务依赖图、662 个子任务；每轮处理一个子任务。论文规定的带反馈设置最多尝试三次，评分门槛为 0.7。若最佳尝试不是最后一次，系统在继续前恢复最佳尝试的工作目录。<a href="https://arxiv.org/html/2610.21074" target="_blank" rel="noreferrer">论文方法与评分循环附录</a></p><p>本次研究沿用同日分析阶段的内部实验，而未重新运行评测。分析阶段从固定版本源码中抽出选择最佳尝试的原函数，使用四组人工输入执行：</p><table tabindex="0"><thead><tr><th>人工评分序列</th><th>原函数选择</th><th>可以说明什么</th></tr></thead><tbody><tr><td>0.6、0.5、0.4</td><td>第一次，0.6</td><td>最高分也可能低于门槛</td></tr><tr><td>0.4、0.8、0.8</td><td>第二次，0.8</td><td>同分时保留最早者</td></tr><tr><td>两次均无评分</td><td>无选中结果</td><td>没有评分不同于得到零分</td></tr><tr><td>0、0</td><td>第一次，0</td><td>零分仍是可供选择的评分</td></tr></tbody></table><p>来源：2026-10-22 内部隔离探针；执行的是固定版本原选择函数，输入为合成数据。门槛比较与“是否需要恢复”的条件由探针另行计算，不是完整运行器的执行结果。源码固定于 <a href="https://huggingface.co/datasets/gideonshaked/OmicsBench/raw/a14a3e5db031f76dcc463281ff5e1cba7c14b4e3/omicsbench_runner/src/omicsbench/_orchestrator/grading_loop.py" target="_blank" rel="noreferrer">a14a3e5 版本的评分循环</a>。</p><p>这里没有发现选择器缺陷。选最高分本来就不等于判定过关。第二组也不是对真实循环轨迹的复现：在 0.7 门槛下，循环会在第一次得到 0.8 时停止，未必产生后一个 0.8。它只是一项平分控制。</p><h2 id="恢复文件-还缺哪一种证据" tabindex="-1">恢复文件，还缺哪一种证据？ <a class="header-anchor" href="#恢复文件-还缺哪一种证据" aria-label="Permalink to &quot;恢复文件，还缺哪一种证据？&quot;">​</a></h2><p>已读源码显示，带反馈的每次尝试都会保存工作目录快照，快照失败会抛出错误；需要恢复时会先停止智能体进程，再恢复选中目录。这支持对实现路径的描述，不能冒充本次已经实际执行文件恢复。内部探针没有运行快照、恢复、模型调用、评分数据库或科学计算。</p><p>更深一层的问题是：恢复到得分最高的文件，能否说明错误分析已被纠正？论文作者将带反馈后的收益明确称为真正恢复的上界，因为迎合评分的程度尚未量化。作者还报告了在反馈下穷举选项、替换选择标准等失败现象。我们据此作出的研究解释是，评分结果需要与过程证据分开：分析数据、执行步骤和输出之间若缺少可检查的关联，较高得分不能单独承担过程纠错的结论。<a href="https://arxiv.org/html/2610.21074" target="_blank" rel="noreferrer">论文第 4.4、4.5 节及局限</a></p><p>对话上下文和已恢复文件也可能处于不同历史位置，后续提示会说明目录恢复。这个实现事实提出了依赖一致性问题，但本次没有测量它会造成多少后续错误；不能把一种可能的风险写成已观察到的故障率。</p><h2 id="两个基准中的-更好-并非同一件事" tabindex="-1">两个基准中的“更好”并非同一件事 <a class="header-anchor" href="#两个基准中的-更好-并非同一件事" aria-label="Permalink to &quot;两个基准中的“更好”并非同一件事&quot;">​</a></h2><p>ST-Bench（空间转录组计算任务评测基准）给出另一种需要拆开的完成记录。其测试得分按任务组合“可用格式产出率”与“已有产出中的指标通过率”，再跨任务汇总。产出过滤器检查指标能否解析、数值是否有限、是否有正值及是否出现 -1；这是一套操作性评分条件，不能直接改称为独立核验过的科学计算。<a href="https://arxiv.org/html/2610.07763" target="_blank" rel="noreferrer">论文第 3.2 节</a></p><p>该论文作者报告，多智能体配置的提升主要体现为产出覆盖更广，条件通过率集中在约 50%–58%；部分配置同时消耗更多推理时间。OmicsBench 作者报告的则是带反馈重试相对于单次执行的评分提升。这些都是来源陈述，本次没有复现两份论文的结果表。<a href="https://arxiv.org/html/2610.07763" target="_blank" rel="noreferrer">ST-Bench 第 4.2–4.3 节</a>、<a href="https://arxiv.org/html/2610.21074" target="_blank" rel="noreferrer">OmicsBench 第 4 节</a></p><p>因此，这个比较只对照证据合同：一个区分产出覆盖与条件质量，另一个加入评分反馈、最佳尝试选择和文件恢复。评测单位、干预和成本口径不同，不能混合分数、合并成普遍的多智能体优势，也不能把带反馈设置当作多智能体处理组。ST-Bench 的查询划分仍在同一批任务内部变化，不是未见任务上的泛化测试。</p><h2 id="把完成记录变成可检查的四个问题" tabindex="-1">把完成记录变成可检查的四个问题 <a class="header-anchor" href="#把完成记录变成可检查的四个问题" aria-label="Permalink to &quot;把完成记录变成可检查的四个问题&quot;">​</a></h2><p>我们的工程建议面向科研评测系统，而不是给某个框架背书。验收一条记录时，依次问：实际保留的是哪次尝试的哪个产物；该尝试得到多少分、评分器是什么版本；分数是否达到明确门槛；有什么材料说明分析过程被纠正，而不仅是答案更接近评分要求。</p><p>前三项可以绑定为尝试身份、产物校验码、评分器版本和门槛判断。第四项需要独立的过程材料，例如可重新计算的中间结果及输入到输出的关联；这是建议核验的证据，不是本次已经具备的能力。即便前三项齐全，第四项仍可能是“未知”。对只承担结果排序职责的选择器，则不应额外要求它证明完整科研过程。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>这里的公开一手事实指论文公开定义和固定源码能直接核对的内容；来源陈述指作者报告但本次未复现的结果。内部实验依据是我们自己的合成输入探针，不是独立第三方证据；研究解释是上述材料所支持的有限推断。本次没有独立复现任一基准完整结果的证据。</p><p>主要材料为 ST-Bench 研究团队的<a href="https://arxiv.org/html/2610.07763" target="_blank" rel="noreferrer">论文预印本，2610.07763v1，2026-10-06</a>，OmicsBench 研究团队的<a href="https://arxiv.org/html/2610.21074" target="_blank" rel="noreferrer">论文预印本，2610.21074v1，2026-10-15</a>，以及其<a href="https://huggingface.co/datasets/gideonshaked/OmicsBench/raw/a14a3e5db031f76dcc463281ff5e1cba7c14b4e3/omicsbench_runner/src/omicsbench/_orchestrator/grading_loop.py" target="_blank" rel="noreferrer">固定版本原始评分源码</a>。内部探针环境为 Windows（操作系统）11、Python（程序设计语言）3.13.15；只执行原函数的隔离片段。94 个私有任务与可运行工件缺口仍限制完整复现。论文发表、被引用或经过评审均不能替代有效性证据，代码成功执行也不建立一般有效性。</p><h2 id="尚未回答的恢复问题" tabindex="-1">尚未回答的恢复问题 <a class="header-anchor" href="#尚未回答的恢复问题" aria-label="Permalink to &quot;尚未回答的恢复问题&quot;">​</a></h2><p>在同等计算预算下，不给反馈的重试还会保留多少收益？排除迎合评分后，又有多少收益来自真正的分析纠错？回答它们需要超出选择器探针的新研究。本篇能交付的是一条审查边界：保留结果和达到门槛分别记录，缺少过程证据时，让恢复判断保持未知。</p>',24))])}const u=n(l,[["render",h]]);export{_ as __pageData,u as default};
